            'observation_complete':False,'complete_originals_retained':False,'type':type(exc).__name__,'detail':str(exc)[:1024],
            'label':LABEL,'nonce':NONCE,'case_pass':False,'automatic_retry':False,'phone_evidence_writes':0})
